async function protectedState(){const result={m1:sha((await db.collection('cmsDrafts').doc('home').get()).data())};for(const name of ['cmsSnapshots','cmsReviewStates','cmsReviews','cmsSourceChecks','cmsSiteImports','cmsSiteSources','cmsIdempotency','cmsAudit'])result[name]=Object.fromEntries((await db.collection(name).get()).docs.map(d=>[d.id,sha(d.data())]));return result;}
async function api(page,pathName,options){return page.evaluate(async({pathName,options})=>(await import(window.__qaAuthUrl)).apiFetch(pathName,options),{pathName,options});}
async function login(page,role='owner'){await page.goto('http://127.0.0.1:5173/');await page.evaluate(()=>{window.__qaAuthUrl=performance.getEntriesByType('resource').map(v=>v.name).find(v=>new URL(v).pathname==='/auth.mjs');if(!window.__qaAuthUrl)throw Error('loaded auth entry missing');});await page.locator('#email').fill(role+'@pinky.test');await page.locator('#password').fill(fixturePassword);await page.locator('#login-submit').click();await expect(page.locator('#session-role')).toHaveText(role.toUpperCase());await expect(page.locator('#hero-editor')).toHaveCount(1);}
