async function restoreContent(page,target){return page.evaluate(async target=>{const {apiFetch}=await import(window.__qaAuthUrl);const {planSiteSave,siteContextFromDraft}=await import('/site-editor.mjs');let draft=await apiFetch('/api/cms/drafts/home-v2');const plan=planSiteSave(draft.content,target,siteContextFromDraft(draft));for(const patch of plan){const result=await apiFetch('/api/cms/drafts/home-v2',{method:'PATCH',headers:{'Content-Type':'application/json','Idempotency-Key':crypto.randomUUID()},body:JSON.stringify({expectedRevision:draft.revision,patch})});draft.revision=result.revision;}const final=await apiFetch('/api/cms/drafts/home-v2');return {content:final.content,revision:final.revision,patches:plan.length};},target);}
test.beforeAll(async()=>{mkdirSync(output,{recursive:true});protectedBefore=await protectedState();server=createServer((request,response)=>{const pathname=new URL(request.url,'http://127.0.0.1:4173').pathname;if(pathname==='/task17-private-native.html'&&privateParentHtml){response.writeHead(200,{'content-type':'text/html; charset=utf-8'});response.end(privateParentHtml);return;}const relative=pathname==='/'?'index.html':pathname.slice(1);if(!artifactRoot||relative.includes('..')||! /^[A-Za-z0-9._/-]+$/.test(relative)){response.writeHead(404);response.end();return;}const file=path.join(artifactRoot,relative);if(!existsSync(file)){response.writeHead(404);response.end();return;}const types={'.html':'text/html; charset=utf-8','.mjs':'text/javascript','.js':'text/javascript','.css':'text/css','.woff':'font/woff','.woff2':'font/woff2','.png':'image/png','.webp':'image/webp','.svg':'image/svg+xml','.mp4':'video/mp4','.pdf':'application/pdf','.json':'application/json'};response.writeHead(200,{'content-type':types[path.extname(file)]??'application/octet-stream'});response.end(readFileSync(file));});await new Promise((resolve,reject)=>{server.once('error',reject);server.listen(4173,'127.0.0.1',resolve);});});
test.beforeEach(async({page,context})=>{extraContexts=[];original=null;originalPath=null;bridge=null;requests=[];pageErrors=[];consoleErrors=[];expectedConsole=[];blocked=0;details={};routeErrors=[];pendingRelease=null;await context.route('**/*',route=>{if(new URL(route.request().url()).hostname!=='127.0.0.1'){blocked++;return route.abort();}return route.continue();});page.on('response',r=>{const u=new URL(r.url());requests.push({method:r.request().method(),origin:u.origin,path:u.pathname,status:r.status()});});page.on('pageerror',e=>pageErrors.push(e.message.slice(0,200)));page.on('console',message=>{if(message.type()==='error'){const text=message.text();if(/Failed to load resource.*(?:400|403|409|422|503)/.test(text))expectedConsole.push('intentional denial response');else consoleErrors.push(text.slice(0,200));}});await login(page);});
test.afterEach(async({page,context},info)=>{let restoreError;details.safeUiErrors=await page.locator('#site-errors').allTextContents();try{for(const extra of extraContexts){try{await extra.close();}catch(error){details.extraCleanupErrors??=[];details.extraCleanupErrors.push(error.message.slice(0,200));}}pendingRelease?.();await page.evaluate(()=>{window.__qaReleaseBody?.();window.__qaReleaseDigest?.();}).catch(()=>{});await page.unrouteAll({behavior:'wait'});await context.unrouteAll({behavior:'wait'});if(original){if(!bridge && (await page.locator('#session-role').textContent())!=='OWNER'){page.once('dialog',dialog=>dialog.accept());if(await page.locator('#logout').isVisible())await page.locator('#logout').click();await login(page);}else if(!await page.locator('#logout').isVisible()){await login(page);}if(bridge){const current=await bridge.service.readDraft({request:bridge.request}),target=structuredClone(original.content),oldIds=new Set(target.settings.clientLogos.map(x=>x.id));for(const added of current.content.settings.clientLogos.filter(x=>!oldIds.has(x.id)))target.settings.clientLogos.push({...added,isVisible:false});for(const family of ['services','projects']){const ids=new Set(target[family].map(x=>x.id));for(const added of current.content[family].filter(x=>!ids.has(x.id)))target[family].push({...added,isVisible:false});}target.sections.find(x=>x.sectionId==='services').serviceOrder=[...original.content.sections.find(x=>x.sectionId==='services').serviceOrder,...target.services.filter(x=>!original.content.services.some(y=>y.id===x.id)).map(x=>x.id)];const {planSiteSave,siteContextFromDraft}=await import('../admin/site-editor.mjs');const plan=planSiteSave(current.content,target,siteContextFromDraft(current));let revision=current.revision;for(const patch of plan){const result=await bridge.service.saveDraft({request:bridge.request,actor:await authorize(bridge.request,'DRAFT_SAVE'),body:{expectedRevision:revision,patch},key:'restore-'+randomUUID(),correlationId:'qa15-restore'});revision=result.revision;}const final=await bridge.service.readDraft({request:bridge.request});details.restoration={namespace:true,exactRetainedTarget:sha(final.content)===sha(target),originalExistingRecordsRestored:original.content.settings.clientLogos.every(x=>sha(final.content.settings.clientLogos.find(y=>y.id===x.id))===sha(x)),addedRetainedHidden:['services','projects'].every(family=>final.content[family].filter(x=>!original.content[family].some(y=>y.id===x.id)).every(x=>!x.isVisible)),revision:final.revision,historyRetained:true,expectedTargetHash:sha(target),restoredTargetHash:sha(final.content)};expect(details.restoration.exactRetainedTarget).toBe(true);expect(details.restoration.originalExistingRecordsRestored).toBe(true);expect(details.restoration.addedRetainedHidden).toBe(true);
 }else{const result=await restoreContent(page,original.content);details.restoration={exactContent:sha(result.content)===sha(original.content),revision:result.revision,patches:result.patches,historyRetained:true};expect(details.restoration.exactContent).toBe(true);}}}catch(error){restoreError=error;details.restorationError=error.message.slice(0,300);}finally{const file=info.title.replace(/[^A-Za-z0-9_-]/g,'_')+'.json';const record={test:info.title,status:info.status,requests,blocked,pageErrors,consoleErrors,expectedConsole,routeErrors,...details};writeFileSync(path.join(output,file),JSON.stringify(record,null,2));suite.groups.push({test:info.title,status:info.status,runtime:path.join(output,file)});}if(restoreError)throw restoreError;expect(details.extraCleanupErrors??[]).toEqual([]);expect(blocked).toBe(0);expect(pageErrors).toEqual([]);expect(consoleErrors).toEqual([]);});
test.afterAll(async()=>{try{const after=await protectedState();expect(after.m1).toBe(protectedBefore.m1);for(const family of Object.keys(protectedBefore).filter(x=>x!=='m1'))for(const [id,hash] of Object.entries(protectedBefore[family]))expect(after[family][id]).toBe(hash);suite.canonicalM1Unchanged=true;suite.preexistingHistoryUnchanged=true;writeFileSync(path.join(output,'suite.json'),JSON.stringify(suite,null,2));console.log('TASK17_EVIDENCE '+path.relative(ROOT,output));}finally{server.closeAllConnections();await new Promise(resolve=>server.close(resolve));await db.terminate();}});


async function contactFit(pageOrFrame,label){await expect.poll(()=>pageOrFrame.locator('.contact-person-icon img').evaluate(n=>n.complete&&n.naturalWidth)).toBe(969);const metrics=await pageOrFrame.locator('.contact-person-icon img').evaluate(image=>{const box=n=>{const r=n.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height,right:r.right,bottom:r.bottom};};return{image:box(image),parent:box(image.parentElement),naturalWidth:image.naturalWidth,naturalHeight:image.naturalHeight,objectFit:getComputedStyle(image).objectFit};});expect(metrics.image.width).toBeLessThanOrEqual(55);expect(metrics.image.height).toBeLessThanOrEqual(55);expect(metrics.image.x).toBeGreaterThanOrEqual(metrics.parent.x);expect(metrics.image.y).toBeGreaterThanOrEqual(metrics.parent.y);expect(metrics.image.right).toBeLessThanOrEqual(metrics.parent.right);expect(metrics.image.bottom).toBeLessThanOrEqual(metrics.parent.bottom);expect(metrics.objectFit).toBe('contain');expect(metrics.naturalWidth).toBe(969);expect(metrics.naturalHeight).toBe(905);details.contactFit??=[];details.contactFit.push({label,...metrics});}
const keys=(value,expected)=>expect(Object.keys(value).sort()).toEqual([...expected].sort());
const summaryKeys=['id','draftId','draftRevision','contentHash','mediaManifestHash','schemaVersion','templateVersion','submittedBy','submittedAt'];
