async function ready(page){await captureOriginal(page);await selectSite(page);await expect(page.locator('#site-review-panel')).toBeVisible();}
async function changeRole(page,role){await page.locator('#logout').click();await login(page,role);await selectSite(page);}
async function selected(page,id){await page.locator('#site-snapshot-id').fill(id);await page.locator('#site-snapshot-load').click();await expect(page.locator('#site-snapshot-summary')).toContainText(id);await expect(page.locator('[data-claim-path]').first()).toBeVisible();return api(page,'/api/cms/snapshots/'+id);}
async function submit(page,message='Synthetic automated QA snapshot; not editorial acceptance'){
 const draft=await api(page,'/api/cms/drafts/home-v2');let receipt;const listener=async response=>{if(response.request().method()==='POST'&&new URL(response.url()).pathname==='/api/cms/snapshots'&&response.status()===201)receipt=await response.json();};page.on('response',listener);
 try{await page.locator('#site-submit-message').fill(message);await page.locator('#site-snapshot-submit').click();await expect.poll(()=>receipt?.id).toBeTruthy();await expect(page.locator('#site-snapshot-summary')).toContainText(receipt.id);keys(receipt,summaryKeys);expect(receipt.draftId).toBe('home-v2');expect(receipt.draftRevision).toBe(draft.revision);const response=await api(page,'/api/cms/snapshots/'+receipt.id);keys(response,['summary','snapshot','reviewState','review','sourceCatalog']);expect(response.summary).toEqual(receipt);expect(response.snapshot.content).toEqual(draft.content);expect(receipt.mediaManifestHash).toBe(sha(response.snapshot.mediaManifest));expect(receipt.contentHash).toBe(sha({content:draft.content,mediaManifestHash:receipt.mediaManifestHash,schemaVersion:2,templateVersion:'m2-site-baseline-v1'}));details.snapshot={id:receipt.id,contentHash:receipt.contentHash,draftRevision:receipt.draftRevision};return response;}finally{page.off('response',listener);}
}
async function sourceBatch(page,paths){
 for(const control of await page.locator('[data-source-select]').all())await control.uncheck();
 for(const claimPath of paths){const group=page.locator('[data-claim-path]').filter({has:page.locator(`[data-source-select]`)}).filter({has:page.locator(`[data-source-id]`)}).and(page.locator(`[data-claim-path="${claimPath}"]`));await group.locator('[data-source-select]').check();const supplied=group.locator('[data-source-id="baseline-source"]');if(await supplied.count()&&await supplied.isEnabled())await supplied.check();else{await group.locator('[data-source-id="baseline-credential"]').check();await group.locator('[data-source-pages]').fill('7,8');}}
 const response=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/api/cms/source-checks');await page.locator('#site-source-submit').click();const result=await response;expect(result.status()).toBe(201);const receipt=await result.json();keys(receipt,sourceKeys);await expect(page.locator('#site-source-revision')).toContainText(String(receipt.sourceRevision));return receipt;
}
async function allPages(page,id,pageSize=20){let cursor,view,sourceRevision;const checks=[];const seen=new Set();do{const result=await api(page,'/api/cms/snapshots/'+id+'/source-checks?pageSize='+pageSize+(cursor?'&cursor='+encodeURIComponent(cursor):''));keys(result,['snapshotId','contentHash','view','sourceRevision','checks','nextCursor']);expect(result.snapshotId).toBe(id);expect(new TextEncoder().encode(JSON.stringify(result)).length).toBeLessThanOrEqual(131072);if(view!==undefined){expect(result.view).toBe(view);expect(result.sourceRevision).toBe(sourceRevision);}view=result.view;sourceRevision=result.sourceRevision;for(const record of result.checks){expect(seen.has(record.id)).toBe(false);seen.add(record.id);checks.push(record);}cursor=result.nextCursor;}while(cursor);return{checks,view,sourceRevision};}
async function attestAll(page,response){const paths=await page.locator('[data-claim-path]').evaluateAll(nodes=>nodes.map(n=>n.dataset.claimPath));expect(paths.length).toBe(29);expect(new Set(paths).size).toBe(29);for(let i=0;i<paths.length;i+=16)await sourceBatch(page,paths.slice(i,i+16));const current=await api(page,'/api/cms/snapshots/'+response.snapshot.id);expect(current.reviewState.sourceRevision).toBe(2);return allPages(page,response.snapshot.id);}
async function decide(page,outcome,declaration='NO_FACTUAL_CLAIMS',note='Synthetic automated decision; not human editorial approval'){
 await page.locator('#site-review-outcome').selectOption(outcome);await page.locator('#site-review-note').fill(note);if(declaration!==undefined)await page.locator('#site-creative-declaration').selectOption(declaration);const response=page.waitForResponse(r=>r.request().method()==='POST'&&new URL(r.url()).pathname==='/api/cms/reviews');await page.locator('#site-review-submit').click();const result=await response;return{status:result.status(),body:await result.json()};
}
async function previewReady(page){await expect(page.locator('#preview')).toHaveAttribute('srcdoc',/<html/);const frame=page.frames().find(f=>f.parentFrame());expect(frame).toBeTruthy();await frame.locator('.hero').waitFor();await frame.evaluate(async()=>{await document.fonts.ready;const image=document.querySelector('.hero-image');if(image&&!image.complete)await Promise.race([image.decode().catch(()=>{}),new Promise(resolve=>setTimeout(resolve,5000))]);});return frame;}
async function capture(page,label,selector='#site-review-panel'){await page.locator(selector).scrollIntoViewIfNeeded();await page.screenshot({path:path.join(output,label+'.png')});}
async function downloadedEnvelope(page,label){const download=page.waitForEvent('download');await page.locator('#site-qa-download').click();await expect(page.locator('#site-qa-link')).toBeVisible();await page.locator('#site-qa-link').click();const file=path.join(ROOT,'.local/cache/m2',runId+'-'+label+'.json');await(await download).saveAs(file);chmodSync(file,0o600);const bytes=readFileSync(file),value=JSON.parse(bytes);keys(value,['qaEnvelopeVersion','snapshot','reviewState','review','sourceChecks']);expect(value.qaEnvelopeVersion).toBe(2);expect(bytes.length).toBeLessThanOrEqual(1048576);expect(value.sourceChecks.map(c=>c.id).sort()).toEqual([...value.review.sourceCheckIds].sort());expect(value.review.attestationSetHash).toBe(sha([...value.sourceChecks].sort((a,b)=>a.claimPath.localeCompare(b.claimPath)||a.id.localeCompare(b.id))));details.envelope={path:file,sha256:createHash('sha256').update(bytes).digest('hex'),bytes:bytes.length,pins:value.sourceChecks.length};return{file,value};}

async function monitoredContext(browser,options){const context=await browser.newContext(options),record={responses:[],blocked:0,pageErrors:[],consoleErrors:[],privateStorageEmpty:true};extraContexts.push(context);details.extraContexts??=[];details.extraContexts.push(record);await context.route('**/*',route=>{if(new URL(route.request().url()).hostname!=='127.0.0.1'){record.blocked++;return route.abort();}return route.continue();});context.on('page',p=>{p.on('pageerror',e=>record.pageErrors.push(e.message));p.on('console',m=>{if(m.type()==='error')record.consoleErrors.push(m.text().slice(0,200));});p.on('response',r=>record.responses.push({origin:new URL(r.url()).origin,path:new URL(r.url()).pathname,status:r.status()}));});const close=context.close.bind(context);let closed=false;context.close=async()=>{if(closed)return;closed=true;try{for(const p of context.pages()){const storage=await p.evaluate(async()=>({local:localStorage.length,session:sessionStorage.length,indexedDatabases:(await indexedDB.databases()).length,cacheStorage:(await caches.keys()).length}));expect(storage).toEqual({local:0,session:0,indexedDatabases:0,cacheStorage:0});record.storage=storage;expect(await context.cookies()).toEqual([]);}}finally{await close();}expect(record.blocked).toBe(0);expect(record.pageErrors).toEqual([]);expect(record.consoleErrors).toEqual([]);for(const response of record.responses){expect(response.status).toBeLessThan(400);expect(response.path).not.toMatch(/content.js|app.js|firebase|baseline-site|baseline-provenance|source-checks/);}};return context;}
async function childArtifactCapture(page,frame,width,height,label){
 await page.locator('#preview-width').selectOption(String(width));await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
 const before=await page.locator('#preview').evaluate(f=>({srcdoc:f.getAttribute('srcdoc'),sandbox:f.getAttribute('sandbox'),style:f.getAttribute('style')}));
 const saved=await page.evaluate(({width,height})=>{const f=document.querySelector('#preview'),v=f.parentElement,old={frame:f.getAttribute('style'),parent:v.getAttribute('style')};v.style.cssText='overflow:visible;width:'+width+'px;height:'+height+'px';return old;},{width,height});
 try{await page.setViewportSize({width:width+80,height:height+100});await page.locator('#preview').scrollIntoViewIfNeeded();await frame.evaluate(()=>document.fonts.ready);expect(await frame.evaluate(()=>({width:innerWidth,height:innerHeight}))).toEqual({width,height});await page.locator('#preview').screenshot({path:path.join(output,label+'.png')});}finally{await page.evaluate(saved=>{const f=document.querySelector('#preview');for(const [node,key] of [[f,'frame'],[f.parentElement,'parent']])saved[key]===null?node.removeAttribute('style'):node.setAttribute('style',saved[key]);},saved);}
 const after=await page.locator('#preview').evaluate(f=>({srcdoc:f.getAttribute('srcdoc'),sandbox:f.getAttribute('sandbox'),style:f.getAttribute('style')}));expect(after).toEqual(before);details.childCapture={parentLayoutOverrideOnly:true,srcdocHash:sha(before.srcdoc),sandboxPreserved:true,restored:true};
}
