 const snapshots=(await db.collection('cmsSnapshots').get()).docs.filter(d=>d.data().schemaVersion===1),keysBefore=(await db.collection('cmsIdempotency').get()).docs.map(d=>d.data()).filter(v=>v.state==='COMPLETED'&&v.statusCode===201&&v.response?.schemaVersion===1);let record;for(const d of snapshots){const key=keysBefore.find(k=>k.response.id===d.id);if(key){record={id:d.id,stored:d.data(),receipt:key.response};break;}}expect(record,'real preexisting v1 completed artifact required').toBeTruthy();const value=await api(page,'/api/cms/snapshots/'+record.id);keys(value,['snapshot','reviewState']);const snapshot=value.snapshot,mediaHash=sha(snapshot.mediaManifest);expect(snapshot.contentHash).toBe(sha({content:snapshot.content,mediaManifestHash:mediaHash,schemaVersion:1,templateVersion:'m1-hero-split-v1'}));expect(snapshot.mediaManifestHash).toBe(mediaHash);const fields=['id','draftRevision','contentHash','mediaManifestHash','schemaVersion','templateVersion','submittedBy','submittedAt'];keys(record.receipt,fields);expect(record.receipt).toEqual(Object.fromEntries(fields.map(k=>[k,snapshot[k]])));const bytes=readFileSync(path.join(ROOT,'tests/fixtures/approved-hero.json'));expect(bytes.length).toBe(5409);expect(createHash('sha256').update(bytes).digest('hex')).toBe('364f4c393753a8505694efd7f454bfa8740e3c7ba2d51fe5252450397364fd3d');details.archive={preexisting:true,id:record.id,exactEightFieldReceipt:true,readOnly:true,oldReplay:false};
