 await ready(page);const edits={'#site-header-cta':'Task17 contact CTA','#site-hero-note':'Task17 saved Hero note','#site-seo-title':'Task17 saved SEO title','#site-work-intro':'Task17 saved Work introduction','#site-services-intro':'Task17 saved Services introduction','#site-about-lead':'Task17 saved About facts','#site-ip-description':'Task17 saved IP description','#site-contact-intro':'Task17 saved Contact introduction','#site-footer-descriptor':'Task17 saved Footer descriptor','#site-contact-email':'task17-saved@example.test'};
